"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Bike, Package, CheckCircle2, Navigation, MapPin } from "lucide-react"
import { useDriverStore, DriverStoreProvider } from "@/lib/store/driver-store"
import { Button } from "@/components/ui/button"
import { DriverMap } from "./driver-map"

function DriverDashboardContent() {
  const { state, acceptOrder, completeOrder } = useDriverStore()

  return (
    <div className="min-h-screen bg-background">
      {/* Header Fijo para Repartidor */}
      <header className="sticky top-0 z-10 bg-card border-b border-border p-4 shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <h1 className="text-xl font-bold flex items-center gap-2">
            <Bike className="h-6 w-6 text-primary" />
            Imperial Delivery
          </h1>
          <div className="flex items-center gap-2">
            <div className="h-2 w-2 bg-green-500 rounded-full animate-pulse" />
            <span className="text-sm font-medium text-muted-foreground">En línea</span>
          </div>
        </div>
      </header>

      <main className="p-4 md:p-8 max-w-7xl mx-auto space-y-8">
        {/* PEDIDO ACTIVO */}
        {state.activeDelivery ? (
          <section className="bg-primary/5 border-2 border-primary rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-primary flex items-center gap-2">
                <Navigation className="h-6 w-6" />
                Entrega en Curso
              </h2>
              <span className="bg-primary text-primary-foreground px-3 py-1 rounded-full text-sm font-mono">
                #{state.activeDelivery.id.slice(-6)}
              </span>
            </div>
            
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <div className="bg-card p-4 rounded-xl border border-border">
                  <p className="text-sm text-muted-foreground mb-1 font-semibold uppercase">Cliente</p>
                  <p className="text-lg font-bold">{state.activeDelivery.customerName}</p>
                  <p className="text-primary font-medium">{state.activeDelivery.customerPhone}</p>
                </div>
                <div className="bg-card p-4 rounded-xl border border-border">
                  <p className="text-sm text-muted-foreground mb-1 font-semibold uppercase">Dirección</p>
                  <p className="text-lg">{state.activeDelivery.deliveryAddress}</p>
                </div>
                <Button 
                  onClick={() => completeOrder(state.activeDelivery!.id)}
                  className="w-full h-16 text-xl font-bold bg-green-600 hover:bg-green-700 shadow-xl"
                >
                  <CheckCircle2 className="h-6 w-6 mr-2" />
                  ENTREGA COMPLETADA
                </Button>
              </div>
              
              <div className="h-[300px] rounded-xl overflow-hidden border border-border">
                <DriverMap 
                  driverLocation={state.currentLocation}
                  deliveryLocation={state.activeDelivery.coordinates}
                  deliveryAddress={state.activeDelivery.deliveryAddress}
                />
              </div>
            </div>
          </section>
        ) : (
          /* PEDIDOS DISPONIBLES */
          <section className="space-y-4">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <Package className="h-6 w-6 text-muted-foreground" />
              Pedidos Listos para Retirar
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              <AnimatePresence>
                {state.availableOrders.map((order) => (
                  <motion.div
                    key={order.id}
                    layout
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.9 }}
                    className="bg-card border border-border rounded-xl p-5"
                  >
                    <div className="flex justify-between items-start mb-4">
                      <span className="font-mono font-bold">#{order.id.slice(-6)}</span>
                      <span className="text-green-500 font-bold text-lg">${order.totalPrice.toFixed(2)}</span>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-muted-foreground mb-4">
                      <MapPin className="h-4 w-4" />
                      <span className="truncate">{order.deliveryAddress}</span>
                    </div>
                    <Button 
                      onClick={() => acceptOrder(order.id)}
                      className="w-full bg-primary hover:bg-primary/90"
                    >
                      ACEPTAR PEDIDO
                    </Button>
                  </motion.div>
                ))}
              </AnimatePresence>
              {state.availableOrders.length === 0 && (
                <div className="col-span-full py-12 text-center text-muted-foreground italic border border-dashed rounded-xl">
                  Esperando nuevos pedidos de la cocina...
                </div>
              )}
            </div>
          </section>
        )}
      </main>
    </div>
  )
}

export function DriverDashboard() {
  return (
    <DriverStoreProvider>
      <DriverDashboardContent />
    </DriverStoreProvider>
  )
}