"use client"

import { createContext, useContext, useReducer, useEffect, type ReactNode, type Dispatch } from "react"
import type { Order } from "@/lib/types"
import { pb } from "@/lib/data/pocketbase"

interface DriverState {
  availableOrders: Order[]
  activeDelivery: Order | null
  completedDeliveries: Order[]
  currentLocation: { lat: number; lng: number }
}

type DriverAction =
  | { type: "SET_INITIAL_DATA"; payload: { available: Order[]; active: Order | null; completed: Order[] } }
  | { type: "UPSERT_AVAILABLE"; payload: Order }
  | { type: "REMOVE_AVAILABLE"; payload: string }
  | { type: "SET_ACTIVE"; payload: Order | null }

const initialState: DriverState = {
  availableOrders: [],
  activeDelivery: null,
  completedDeliveries: [],
  currentLocation: { lat: -34.6037, lng: -58.3816 },
}

function driverReducer(state: DriverState, action: DriverAction): DriverState {
  switch (action.type) {
    case "SET_INITIAL_DATA":
      return { ...state, availableOrders: action.payload.available, activeDelivery: action.payload.active, completedDeliveries: action.payload.completed }
    case "UPSERT_AVAILABLE":
      return { ...state, availableOrders: [...state.availableOrders.filter(o => o.id !== action.payload.id), action.payload] }
    case "REMOVE_AVAILABLE":
      return { ...state, availableOrders: state.availableOrders.filter(o => o.id !== action.payload) }
    case "SET_ACTIVE":
      return { ...state, activeDelivery: action.payload }
    default:
      return state
  }
}

const DriverStateContext = createContext<DriverState | null>(null)
const DriverDispatchContext = createContext<Dispatch<DriverAction> | null>(null)

export function DriverStoreProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(driverReducer, initialState)

  useEffect(() => {
    const driverId = pb.authStore.model?.id
    if (!driverId) return

    const fetchOrders = async () => {
      try {
        const records = await pb.collection("orders").getFullList({
          filter: `orderMode = "delivery" && status != "cancelled"`
        })
        const orders = records as unknown as Order[]
        dispatch({
          type: "SET_INITIAL_DATA",
          payload: {
            available: orders.filter(o => o.status === "ready"),
            active: orders.find(o => o.status === "out-for-delivery" && o.driverId === driverId) || null,
            completed: orders.filter(o => o.status === "delivered" && o.driverId === driverId)
          }
        })
      } catch (e) { console.error(e) }
    }

    fetchOrders()

    pb.collection("orders").subscribe("*", (e) => {
      const order = e.record as unknown as Order
      if (order.status === "ready") {
        dispatch({ type: "UPSERT_AVAILABLE", payload: order })
      } else if (order.status === "out-for-delivery" && order.driverId === driverId) {
        dispatch({ type: "SET_ACTIVE", payload: order })
        dispatch({ type: "REMOVE_AVAILABLE", payload: order.id })
      } else {
        dispatch({ type: "REMOVE_AVAILABLE", payload: order.id })
      }
    })

    return () => { pb.collection("orders").unsubscribe("*") }
  }, [])

  return (
    <DriverStateContext.Provider value={state}>
      <DriverDispatchContext.Provider value={dispatch}>{children}</DriverDispatchContext.Provider>
    </DriverStateContext.Provider>
  )
}

export function useDriverStore() {
  const state = useContext(DriverStateContext)
  const dispatch = useContext(DriverDispatchContext)
  if (!state || !dispatch) throw new Error("useDriverStore must be used within DriverStoreProvider")

  const acceptOrder = async (orderId: string) => {
    const driverId = pb.authStore.model?.id
    await pb.collection("orders").update(orderId, { 
      status: "out-for-delivery",
      driverId: driverId 
    })
  }

  const completeOrder = async (orderId: string) => {
    await pb.collection("orders").update(orderId, { status: "delivered" })
    dispatch({ type: "SET_ACTIVE", payload: null })
  }

  return { state, dispatch, acceptOrder, completeOrder }
}